import math

# Query and three documents; B points the same way as the query but is short.
q = [1.0, 1.0]
docs = {"A": [10.0, 0.0], "B": [1.0, 1.2], "C": [0.0, 2.0]}

def dot(a, b): return sum(x * y for x, y in zip(a, b))
def norm(a): return math.sqrt(dot(a, a))
def cos(a, b): return dot(a, b) / (norm(a) * norm(b))
def euc(a, b): return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))
def unit(a):
    n = norm(a)
    return [x / n for x in a]

def show(title, qv, dv):
    print(title)
    # Cosine and dot: bigger is better. Euclidean: smaller is better.
    print("  cosine :", sorted(dv, key=lambda k: -cos(qv, dv[k])))
    print("  dot    :", sorted(dv, key=lambda k: -dot(qv, dv[k])))
    print("  euclid :", sorted(dv, key=lambda k: euc(qv, dv[k])))

print("query:", q, "docs:", docs)
show("RAW vectors (lengths differ): rankings disagree", q, docs)
nd = {k: unit(v) for k, v in docs.items()}
show("UNIT vectors: all three agree", unit(q), nd)

# For unit vectors: euclid^2 == 2 - 2*cosine
a, b = nd["A"], nd["B"]
print("euclid^2 =", round(euc(a, b) ** 2, 4), " 2-2*cos =", round(2 - 2 * cos(a, b), 4))

K = 60  # damping constant

bm25 = ["doc_error_E4471", "doc_billing", "doc_login", "doc_refund", "doc_api"]
vector = ["doc_login", "doc_sso", "doc_error_E4471", "doc_api", "doc_pricing"]

def rrf(lists, k=K):
    score = {}
    for ranking in lists:
        for rank, doc in enumerate(ranking, start=1):  # rank starts at 1
            score[doc] = score.get(doc, 0.0) + 1.0 / (k + rank)
    return sorted(score.items(), key=lambda kv: -kv[1])

print("BM25  :", bm25)
print("vector:", vector)
for doc, s in rrf([bm25, vector]):
    print(f"{doc:16s} {s:.4f}")
# A doc ranked high by BOTH lists beats one ranked first by only one list.
print("small k=1 top:", rrf([bm25, vector], k=1)[0][0])

