const K = 60; // damping constant

const bm25 = ["doc_error_E4471", "doc_billing", "doc_login", "doc_refund", "doc_api"];
const vector = ["doc_login", "doc_sso", "doc_error_E4471", "doc_api", "doc_pricing"];

function rrf(lists, k = K) {
  const score = new Map();
  for (const ranking of lists) {
    ranking.forEach((doc, i) => {
      // rank starts at 1, so rank = i + 1
      score.set(doc, (score.get(doc) || 0) + 1 / (k + i + 1));
    });
  }
  return [...score.entries()].sort((a, b) => b[1] - a[1]);
}

console.log("BM25  :", "[" + bm25.map((d) => "'" + d + "'").join(", ") + "]");
console.log("vector:", "[" + vector.map((d) => "'" + d + "'").join(", ") + "]");
for (const [doc, s] of rrf([bm25, vector])) {
  console.log(doc.padEnd(16) + " " + s.toFixed(4));
}
// A doc ranked high by BOTH lists beats one ranked first by only one list.
console.log("small k=1 top:", rrf([bm25, vector], 1)[0][0]);

