import math

# Golden set: query -> relevant doc ids. "results" = ranked ids a system returned.
golden = {
    "q1": {"a", "b"},
    "q2": {"c"},
    "q3": {"d", "e"},
}
results = {
    "q1": ["a", "x", "b", "y", "z"],
    "q2": ["x", "y", "c", "z", "w"],
    "q3": ["x", "y", "z", "w", "v"],
}

def recall_at_k(rel, ranked, k):
    return len(rel & set(ranked[:k])) / len(rel)

def mrr(rel, ranked):
    for pos, d in enumerate(ranked, start=1):
        if d in rel: return 1.0 / pos       # reciprocal rank of first hit
    return 0.0

def ndcg_at_k(rel, ranked, k):
    dcg = sum(1 / math.log2(i + 2) for i, d in enumerate(ranked[:k]) if d in rel)
    ideal = sum(1 / math.log2(i + 2) for i in range(min(len(rel), k)))
    return dcg / ideal

for k in (1, 3, 5):
    r = sum(recall_at_k(golden[q], results[q], k) for q in golden) / len(golden)
    print(f"recall@{k} = {r:.3f}")
print("MRR      =", round(sum(mrr(golden[q], results[q]) for q in golden) / len(golden), 3))
print("nDCG@5   =", round(sum(ndcg_at_k(golden[q], results[q], 5) for q in golden) / len(golden), 3))
for q in golden:   # per-query view shows which queries fail
    print(q, "recall@5 =", recall_at_k(golden[q], results[q], 5))
